-- Disposable baseline from the 2026-09-14 read-only schema audit. No remote data.
create role anon; create role authenticated; create role service_role bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create or replace function public.protect_other_ingredient_category()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if pg_catalog.btrim(old.name) = 'อื่น ๆ' then
    if tg_op = 'DELETE' then
      raise exception 'หมวดวัตถุดิบ "อื่น ๆ" ไม่สามารถลบได้'
        using errcode = '23514';
    end if;

    if new.name is distinct from old.name then
      raise exception 'หมวดวัตถุดิบ "อื่น ๆ" ไม่สามารถเปลี่ยนชื่อได้'
        using errcode = '23514';
    end if;

    if new.is_active is false
      and new.is_active is distinct from old.is_active then
      raise exception 'หมวดวัตถุดิบ "อื่น ๆ" ไม่สามารถปิดใช้งานได้'
        using errcode = '23514';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


create function auth.role() returns text language sql stable as $$ select current_setting('request.jwt.claim.role',true) $$;
