CREATE OR REPLACE FUNCTION public.complete_order_payment(p_order_id uuid, p_payment_method text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_payment_id public.payments.id%type;
begin
  -- ตรวจสอบช่องทางชำระเงิน
  if p_payment_method not in ('cash', 'qr_code') then
    raise exception 'ช่องทางชำระเงินไม่ถูกต้อง';
  end if;

  -- ค้นหาและล็อกออเดอร์
  select *
  into v_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ไม่พบออเดอร์นี้';
  end if;

  -- ต้องพร้อมเสิร์ฟก่อนรับชำระ
  if v_order.status <> 'ready' then
    raise exception 'ออเดอร์ต้องอยู่ในสถานะพร้อมเสิร์ฟก่อนรับชำระ';
  end if;

  -- สต็อกต้องถูกหักตอนเริ่มทำอาหารแล้ว
  if not coalesce(v_order.stock_deducted, false) then
    raise exception 'ออเดอร์นี้ยังไม่ได้หักสต็อก';
  end if;

  -- ป้องกันการชำระซ้ำ โดยตรวจทุกสถานะที่ไม่ใช่ล้มเหลว
  if exists (
    select 1
    from public.payments
    where order_id = p_order_id
      and status not in ('failed', 'cancelled')
  ) then
    raise exception 'ออเดอร์นี้ชำระเงินแล้ว';
  end if;

  -- บันทึกการชำระเงิน
  insert into public.payments (
    order_id,
    payment_method,
    amount,
    status,
    paid_at
  )
  values (
    p_order_id,
    p_payment_method,
    v_order.total_amount,
    'paid',
    now()
  )
  returning id into v_payment_id;

  -- ปิดออเดอร์ โดยไม่หักสต็อกซ้ำ
  update public.orders
  set
    status = 'completed',
    updated_at = now()
  where id = p_order_id;

  return jsonb_build_object(
    'success', true,
    'message', 'รับชำระเงินสำเร็จ',
    'order_id', p_order_id,
    'payment_id', v_payment_id,
    'payment_method', p_payment_method,
    'amount', v_order.total_amount
  );
end;
$function$
;
CREATE OR REPLACE FUNCTION public.deduct_ingredient_stock(required_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  item jsonb;
  ingredient_record record;
  required_quantity numeric;
begin
  -- ตรวจทุกวัตถุดิบและล็อกแถวไว้ก่อน
  for item in
    select value
    from jsonb_array_elements(required_items)
  loop
    required_quantity :=
      (item->>'quantity')::numeric;

    select id, name, stock_quantity
    into ingredient_record
    from public.ingredients
    where id = (item->>'ingredient_id')::bigint
    for update;

    if not found then
      raise exception
        'ไม่พบวัตถุดิบรหัส %',
        item->>'ingredient_id';
    end if;

    if ingredient_record.stock_quantity < required_quantity then
      raise exception
        'วัตถุดิบ % ไม่เพียงพอ',
        ingredient_record.name;
    end if;
  end loop;

  -- เมื่อทุกอย่างพอแล้ว จึงหักสต็อก
  for item in
    select value
    from jsonb_array_elements(required_items)
  loop
    update public.ingredients
    set stock_quantity =
      stock_quantity - (item->>'quantity')::numeric
    where id = (item->>'ingredient_id')::bigint;
  end loop;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.process_order_stock(p_order_id uuid, required_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_order record;
  item jsonb;
  current_ingredient_id bigint;
  current_quantity numeric;
  updated_ingredient_id bigint;
begin
  select id, stock_deducted
  into current_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ไม่พบออเดอร์นี้';
  end if;

  if current_order.stock_deducted then
    raise exception 'ออเดอร์นี้ถูกหักสต็อกแล้ว';
  end if;

  if required_items is null
     or jsonb_typeof(required_items) <> 'array'
     or jsonb_array_length(required_items) = 0 then
    raise exception 'ไม่พบรายการวัตถุดิบที่ต้องหัก';
  end if;

  for item in
    select value
    from jsonb_array_elements(required_items)
  loop
    current_ingredient_id := (item ->> 'ingredient_id')::bigint;
    current_quantity := (item ->> 'quantity')::numeric;

    if current_ingredient_id is null
       or current_quantity is null
       or current_quantity <= 0 then
      raise exception 'ข้อมูลวัตถุดิบไม่ถูกต้อง';
    end if;

    update public.ingredients
    set stock_quantity = stock_quantity - current_quantity
    where id = current_ingredient_id
      and stock_quantity >= current_quantity
    returning id into updated_ingredient_id;

    if updated_ingredient_id is null then
      if not exists (
        select 1
        from public.ingredients
        where id = current_ingredient_id
      ) then
        raise exception 'ไม่พบวัตถุดิบรหัส %', current_ingredient_id;
      end if;

      raise exception 'วัตถุดิบรหัส % มีจำนวนไม่เพียงพอ', current_ingredient_id;
    end if;

    insert into public.order_ingredient_usages (
      order_id,
      ingredient_id,
      quantity_used
    )
    values (
      p_order_id,
      current_ingredient_id,
      current_quantity
    );

    updated_ingredient_id := null;
  end loop;

  update public.orders
  set stock_deducted = true,
      updated_at = now()
  where id = p_order_id;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.restore_order_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status = 'cancelled'
     and old.status <> 'cancelled'
     and old.stock_deducted = true then
    if old.status = 'completed' then
      raise exception using errcode = 'P0001', message = 'COMPLETED_ORDER';
    end if;

    if not exists (
      select 1
      from public.order_ingredient_usages as usage
      where usage.order_id = old.id
    ) then
      raise exception using errcode = 'P0001', message = 'ORDER_USAGE_NOT_FOUND';
    end if;

    update public.ingredients as ingredient
    set stock_quantity = ingredient.stock_quantity + usage.quantity_used,
        updated_at = now()
    from public.order_ingredient_usages as usage
    where usage.order_id = old.id
      and ingredient.id = usage.ingredient_id;

    new.stock_deducted := false;
  end if;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.deduct_order_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  required_item record;
  current_stock numeric;
  ingredient_name text;
begin
  -- ทำงานเฉพาะตอนเปลี่ยนจากสถานะอื่นมาเป็น confirmed
  -- และออเดอร์นี้ยังไม่เคยหักสต็อก
  if new.status = 'confirmed'
     and old.status is distinct from 'confirmed'
     and coalesce(new.stock_deducted, false) = false then

    for required_item in
      select
        mi.ingredient_id,
        sum(mi.quantity_required * oi.quantity) as total_required
      from public.order_items oi
      join public.menu_ingredients mi
        on mi.menu_id = oi.menu_id
      where oi.order_id = new.id
      group by mi.ingredient_id
      order by mi.ingredient_id
    loop
      -- ล็อกวัตถุดิบทีละรายการ เพื่อป้องกันหลายออเดอร์หักพร้อมกัน
      select
        i.name,
        i.stock_quantity
      into
        ingredient_name,
        current_stock
      from public.ingredients i
      where i.id = required_item.ingredient_id
      for update;

      if not found then
        raise exception
          'ไม่พบข้อมูลวัตถุดิบรหัส %',
          required_item.ingredient_id;
      end if;

      if current_stock < required_item.total_required then
        raise exception
          'วัตถุดิบ "%" ไม่เพียงพอ ต้องใช้ % แต่เหลือ %',
          ingredient_name,
          required_item.total_required,
          current_stock;
      end if;

      update public.ingredients
      set
        stock_quantity = stock_quantity - required_item.total_required,
        updated_at = now()
      where id = required_item.ingredient_id;
    end loop;

    new.stock_deducted := true;
  end if;

  return new;
end;
$function$
;
create view public.menu_stock_availability as  SELECT m.id AS menu_id,
    m.is_available AS manually_available,
        CASE
            WHEN (count(mi.ingredient_id) = 0) THEN false
            WHEN bool_and((COALESCE(i.stock_quantity, (0)::numeric) >= mi.quantity_required)) THEN true
            ELSE false
        END AS stock_available,
        CASE
            WHEN ((m.is_available = true) AND (count(mi.ingredient_id) > 0) AND bool_and((COALESCE(i.stock_quantity, (0)::numeric) >= mi.quantity_required))) THEN true
            ELSE false
        END AS can_order
   FROM ((menus m
     LEFT JOIN menu_ingredients mi ON ((mi.menu_id = m.id)))
     LEFT JOIN ingredients i ON ((i.id = mi.ingredient_id)))
  GROUP BY m.id, m.is_available;
CREATE TRIGGER trigger_deduct_order_stock BEFORE UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION deduct_order_stock();
CREATE TRIGGER trigger_restore_order_stock BEFORE UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION restore_order_stock();
CREATE TRIGGER protect_other_ingredient_category BEFORE DELETE OR UPDATE ON public.ingredient_categories FOR EACH ROW EXECUTE FUNCTION protect_other_ingredient_category();
